SELECT 'decide' AS check_name, * FROM thinkthen.decide('SELECT ''Please refund the duplicate charge.''::text AS record', 'Does the customer request a refund?');
SELECT 'choose' AS check_name, * FROM thinkthen.choose('SELECT ''Please refund the duplicate charge.''::text AS record', 'Which team owns this?', choices => ARRAY['billing','shipping','account']);
SELECT 'tag' AS check_name, * FROM thinkthen.tag('SELECT ''Please refund the duplicate charge.''::text AS record', 'Which topics apply?', labels => ARRAY['refund','delivery','login']);
SELECT 'score' AS check_name, * FROM thinkthen.score('SELECT ''Please refund the duplicate charge.''::text AS record', 'How urgent is this?', levels => ARRAY['low','medium','high']);
SELECT 'filter' AS check_name, * FROM thinkthen.filter('SELECT ''Please refund the duplicate charge.''::text AS record', 'Does the customer request a refund?');
SELECT 'rank' AS check_name, * FROM thinkthen.rank('SELECT ''Please refund the duplicate charge.''::text AS record', 'How urgent is this?', levels => ARRAY['low','medium','high']);
SELECT 'find' AS check_name, * FROM thinkthen.find('SELECT ''Please refund the duplicate charge.''::text AS record', 'When is the meeting?');
SELECT 'annotate' AS check_name, * FROM thinkthen.annotate('SELECT ''Please refund the duplicate charge.''::text AS record', toolbox => '{"refund": {"function": "decide", "question": "Does the customer request a refund?"}}'::jsonb);
SELECT 'recognize' AS check_name, * FROM thinkthen.recognize('SELECT ''Ada works for Acme.''::text AS record', kinds => ARRAY['person','organization']);
SELECT 'relate' AS check_name, * FROM thinkthen.relate('SELECT ''Ada works for Acme.''::text AS record', rules => ARRAY[ROW('works_for','person','organization',NULL,false)::thinkthen.rule]);
